head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.isurCd = "";          // 발행기관코드 (부모 arr[0])
scwin.isurNm = "";          // 발행기관명 — 종목 기준으로 열면 종목약명 (부모 arr[1])
scwin.secugrpId = "";       // 증권그룹ID (부모 arr[2])
scwin.mktId = "";           // 시장구분코드 (부모 arr[3])
scwin.bzProcsNo = "";       // 업무처리번호 — 비어 있으면 신규, 있으면 수정 (부모 arr[4])
scwin.tpCd = "";            // 관리종목지정및해제구분코드 (부모 arr[5] — 이 화면은 쓰지 않음, 원본도 미사용)
scwin.isuCd = "";           // 종목코드 (부모 arr[6], 원본 gubun)
scwin.selTp = "";           // 선택 구분 1: 종목, 2: 발행회사, 3: 전체 (부모 arr[7], 원본 select_gubun)
scwin.curDate = "";         // 서버 현재일 (yyyyMMdd)
scwin.trJob = "";           // 처리구분 I: 저장, U: 수정, D: 삭제
scwin.isSaved = false;      // 저장·수정에 성공했는지 — 닫을 때 부모에 돌려준다
scwin.DSCL_FORM_CD = "68347";   // 공시안내문 서식코드 (원본 arr[0])
scwin.DSCL_MKT_ID = "1";        // 공시안내문 시장구분 (원본 arr[3])
scwin.RSNCD_ADM_DESIGN = "2";   // 관리종목지정사유 (pcc list_common RSNCD_ADM_DESIGN)
scwin.DEFAULT_REMK = "관리종목으로 지정된 경우에도 ETN 매매는 정상적으로 가능합니다.\n";   // 신규 기타 기본값 (원본 fn_setRemk, 2014.12.26 문구)
// 원본 : /etn/ULDSTF08036.gfm (ETN 관리종목지정 우려 예고 팝업)
/*
 * 화면 동작 — (팝업)관리종목지정 우려 예고
 *  - 부모(ULDSTF08035 관리종목지정 우려예고 목록)가 openPopup 의 data 로 연다. 업무처리번호가 없으면 신규, 있으면 수정이다.
 *  - 신규(종목 기준): 부모가 넘긴 종목을 그리드에 두고, 예고일·예정일(또는 주석)·예고사유를 넣어 저장한다. 업무처리번호는 화면이 채번한다(명세).
 *  - 수정: 업무처리번호로 상세(마스터·종목·예고사유)를 조회해 수정·삭제한다. 예고일이 지난 건은 조회 전용이다.
 *  - 공시안내문작성(ULDSTF92024, 서식 68347). 닫힌 뒤 반환 { isSaved } 또는 X 닫기면 부모가 목록을 다시 조회한다.
 *  - 같은 계열: ULDSTF08036_new(발행회사 기준 신규 — 미반입) · 08032 관리종목지정
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF08036/ULDSTF08036.md (§번호는 이 문서의 절)
 */

// 이 화면의 역할→버튼 매핑 — 상태별 활성 정책은 공통(BTN_STATE_MAP)이 보유한다.
scwin.BTN_MAP = {
    save : "btn_Save",          // [저장]
    modify : "btn_Update",      // [수정]
    "delete" : "btn_Delete",    // [삭제]
    guide : "btn_Dscl"          // [안내문작성]
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 30
 * @description 페이지로드
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08036.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 30
 * @description 초기화. 버튼을 잠그고 달력 검사를 건 뒤, 부모 파라미터로 신규·수정을 가른다. (원본 gform onload — §3)
 *
 * 부모는 openPopup 의 3번째 인자를 평면으로 넘기므로 $c.data.getParameter() 로 받는다(원본 fn_GetPar arr 0~7 — §1.2).
 * 로딩 중에는 버튼을 전부 잠근다 — 조회가 실패해도 버튼이 XML 기본값(전부 활성)으로 남지 않게 한다.
 * @param
 * @returns
 * @hidden N
*/
scwin.init = async function () {
    // 1) 로딩 동안 버튼 잠금
    $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);

    // 2) 달력 검사(규칙 37)·서버 현재일
    $c.date.checkCalendarFormat(edt_AdmIsuNotiDd, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_AdmIsuNotiEndDd, "yyyyMMdd");
    scwin.curDate = $c.date.getServerDateTime("yyyyMMdd");

    // 3) 파라미터 수신 — openPopup 의 3번째 인자
    const param = $c.data.getParameter() ?? {};

    scwin.isurCd = param.isurCd ?? "";
    scwin.isurNm = param.isurNm ?? "";
    scwin.secugrpId = param.secugrpId ?? "";
    scwin.mktId = param.mktId ?? "";
    scwin.bzProcsNo = param.bzProcsNo ?? "";
    scwin.tpCd = param.admisuDesignBzTpCd ?? "";
    scwin.isuCd = param.isuCd ?? "";
    scwin.selTp = param.selTp ?? "";

    // 4) 신규 / 수정
    if ($c.util.isEmpty(scwin.bzProcsNo)) {
        scwin.initNewForm();
        return;
    }

    await scwin.applyDetail(scwin.bzProcsNo);
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @event
 * @name scwin.img_SetIsuCd_onclick
 * @description 종목선택 클릭. 원본은 ETN 종목 다건 선택 팝업(fn_PopFindEtnCode)을 열어 고른 종목으로 그리드를 바꿨다. (§6.3)
 *
 * 대응하는 팝업이 아직 전환되지 않았다(08032 와 같은 사정) — 버튼은 두고 안내만 한다(§10 #2).
 * 부모 08035 는 종목 기준(selTp 1)일 때만 이 화면을 신규로 열고, 그때 이 버튼은 잠긴다 — 보통 쓰이지 않는다.
 * @param {Object} e 이벤트 객체
*/
scwin.img_SetIsuCd_onclick = async function (e) {
    try {
        // TODO: ETN 종목 다건 선택 팝업 전환 뒤 연결 (§10 #2)
        await $c.win.alert("ETN 종목 선택 팝업이 아직 준비되지 않았습니다.\n\n관리종목지정 우려예고 목록에서 종목을 선택해 신규 등록하세요.");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08036.img_SetIsuCd_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_rsn_add_onclick
 * @description 사유추가 클릭
 * @param {Object} e 이벤트 객체
*/
scwin.btn_rsn_add_onclick = async function (e) {
    try {
        await scwin.openRsnPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08036.btn_rsn_add_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_rsn_del_onclick
 * @description 사유삭제 클릭. 예고사유 그리드에서 고른 행을 지운다. (원본 dts_Rsn.DeleteRow(RowPosition))
 * @param {Object} e 이벤트 객체
*/
scwin.btn_rsn_del_onclick = async function (e) {
    try {
        const row = grd_rsn.getFocusedRowIndex();
        if (row < 0) return;

        dlt_rsn.removeRow(row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08036.btn_rsn_del_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_Save_onclick
 * @description 저장 버튼 클릭
 * @param {Object} e 이벤트 객체
*/
scwin.btn_Save_onclick = async function (e) {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08036.btn_Save_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_Update_onclick
 * @description 수정 버튼 클릭
 * @param {Object} e 이벤트 객체
*/
scwin.btn_Update_onclick = async function (e) {
    try {
        await scwin.update();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08036.btn_Update_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_Delete_onclick
 * @description 삭제 버튼 클릭
 * @param {Object} e 이벤트 객체
*/
scwin.btn_Delete_onclick = async function (e) {
    try {
        await scwin.remove();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08036.btn_Delete_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_Dscl_onclick
 * @description 안내문작성 버튼 클릭
 * @param {Object} e 이벤트 객체
*/
scwin.btn_Dscl_onclick = async function (e) {
    try {
        await scwin.writeDscl();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08036.btn_Dscl_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectOne
 * @author Inswave
 * @date 2026. 10. 30
 * @description 수정 진입 상세 조회. 업무처리번호의 마스터·종목·예고사유를 한 번에 화면 DataCollection 에 담는다. (원본 fn_search — §5.1)
 *
 * 원본은 searchEtnAdministrativeIssueNoti 를 DIV_IDX 별(MST·ISU_ITM·RSN)로 세 번 불렀다. 명세는 한 번에 돌려준다.
 * @param {String} bzProcsNo 업무처리번호
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
*/
scwin.selectOne = async function (bzProcsNo) {
    dma_mst.setEmptyValue();
    dlt_isu.removeAll();
    dlt_rsn.removeAll();

    const sbmOptions = {
        id : "sbm_selectOne",
        method : "get",
        action : "/api/listing/lstproc/etn/adm-isu-noti/select-one",
        target : "dma_mst=body.mst, dlt_isu=body.isuList, dlt_rsn=body.rsnList",
        isProcessMsg : false
    };

    const requestData = {
        bzProcsNo : bzProcsNo,          // 업무처리번호
        isurCd : scwin.isurCd           // 발행기관코드 — 종목내역 조회 기준 (원본 ISUR_CD)
    };

    // 통신 오류는 공통 오류 핸들러가 안내하고 예외를 던진다.
    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);

    return !!result.responseJSON?.success;
};

/**
 * @method
 * @name scwin.saveTrs
 * @author Inswave
 * @date 2026. 10. 30
 * @description 관리종목지정 우려 예고 등록(I)·수정(U). 마스터·예고사유를 보내고, 성공하면 상세를 다시 조회한다. (원본 fn_save_trs + trs OnSuccess — §5.2)
 *
 * 예고사유의 변경후구분(2)·지정해제구분(3 우려예고)·추가지정여부(N)는 서버가 채운다(원본 fn_save_trs 의 행 루프 — 명세 요청에 없음).
 * 원본의 부모 직접 재조회(fn_parentRefresh)는 반환 규약(isSaved)으로 바꿨다.
 * @param {String} trJob 처리구분 I: 저장, U: 수정
 * @returns {Promise<Boolean>} 처리 성공 여부
 * @hidden N
*/
scwin.saveTrs = async function (trJob) {
    dma_saveResult.setEmptyValue();

    const sbmOptions = {
        id : "sbm_saveTrs",
        method : "post",
        action : (trJob === "I") ? "/api/listing/lstproc/etn/adm-isu-noti/register" : "/api/listing/lstproc/etn/adm-isu-noti/modify",
        target : "dma_saveResult=body",
        mediatype : "application/json",
        isProcessMsg : false
    };

    const requestData = {
        bzProcsNo : scwin.bzProcsNo,                                        // 업무처리번호 (등록은 화면 채번값)
        isurCd : dma_mst.get("isurCd") || scwin.isurCd,                     // 발행기관코드 (상장업무처리로그 기록용)
        isuCd : dma_mst.get("isuCd") || dlt_isu.getCellData(0, "isuCd"),    // 종목코드 (원본 Isu_cd — 그리드 첫 종목)
        admisunotiDd : dma_mst.get("admisunotiDd"),                         // 관리종목지정예고일자
        admisuDesignSchdlDd : dma_mst.get("admisuDesignSchdlDd"),           // 관리종목지정예정일자
        admisuDesignSchdlContn : dma_mst.get("admisuDesignSchdlContn"),     // 관리종목지정예정내용(주석)
        remk : dma_mst.get("remk"),                                         // 기타
        rsnList : dlt_rsn.getAllJSON().map(row => ({
            admisuDesignRsnCd : row.admisuDesignRsnCd,
            admisuDesignRsnNm : row.admisuDesignRsnNm
        }))
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    const jobNm = (trJob === "I") ? "저장" : "수정";

    if (!result.responseJSON?.success || dma_saveResult.get("result") === "F") {
        // "MSG-A002": "[^] 처리 실패하였습니다." — 서버 메시지가 있으면 함께 보인다.
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", jobNm) + ($c.util.isEmpty(dma_saveResult.get("resultMessage")) ? "" : "\n\n" + dma_saveResult.get("resultMessage")));
        return false;
    }

    // "com_complete_0096": "$[0] 되었습니다."
    await $c.win.alert($c.data.getMessage("com_complete_0096", jobNm));
    scwin.isSaved = true;

    // 원본처럼 저장 뒤 상세를 다시 읽는다(trs OnSuccess → fn_search).
    await scwin.applyDetail(scwin.bzProcsNo);

    return true;
};

/**
 * @method
 * @name scwin.removeTrs
 * @author Inswave
 * @date 2026. 10. 30
 * @description 관리종목지정 우려 예고 삭제. 업무처리번호·발행기관코드를 보낸다. 성공하면 { isSaved : true } 로 팝업을 닫는다. (원본 fn_delete + trs OnSuccess — §5.3)
 * @param
 * @returns
 * @hidden N
*/
scwin.removeTrs = async function () {
    dma_saveResult.setEmptyValue();

    const sbmOptions = {
        id : "sbm_removeTrs",
        method : "post",
        action : "/api/listing/lstproc/etn/adm-isu-noti/remove",
        target : "dma_saveResult=body",
        mediatype : "application/json",
        isProcessMsg : false
    };

    const requestData = {
        bzProcsNo : scwin.bzProcsNo,                        // 업무처리번호
        isurCd : dma_mst.get("isurCd") || scwin.isurCd      // 발행기관코드 (상장업무처리로그 기록용)
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);

    if (!result.responseJSON?.success || dma_saveResult.get("result") === "F") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제") + ($c.util.isEmpty(dma_saveResult.get("resultMessage")) ? "" : "\n\n" + dma_saveResult.get("resultMessage")));
        return;
    }

    await $c.win.alert($c.data.getMessage("com_complete_0096", "삭제"));
    await $c.win.closePopup({ isSaved : true });
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.getNewBzProcsNo
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 업무처리번호를 화면에서 채번한다 — 명세 등록 bzProcsNo 「프론트 채번값」. (원본 fn_getNewBzProcNo — §5.4)
 * @returns {Promise<String>} 업무처리번호 (못 받으면 빈 값)
 * @hidden N
*/
scwin.getNewBzProcsNo = async function () {
    // TODO: 채번 응답 모양 미확정 — body 가 문자열인지 { bzProcsNo } 인지 확인 (§10 #3). 지금은 둘 다 받는다(05918 선례).
    const res = await $c.stf.getNewBzProcNo();
    const body = res?.body ?? res;
    return String((typeof body === "object" && body !== null) ? (body.bzProcsNo ?? "") : (body ?? ""));
};

/**
 * @method
 * @name scwin.initNewForm
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 진입. 기타 기본 문구를 넣고, 종목 기준이면 부모가 넘긴 종목을 그리드에 한 행으로 둔다. (원본 fn_new_onload + dts_Mst OnLoadCompleted — §3)
 *
 * 원본은 종목 기준(select_gubun 1)일 때 searchEtnCode 로 그 종목 한 행을 받았다. 명세에 대응 API 가 없어
 * 부모가 넘긴 종목코드·종목약명·발행기관코드로 한 행을 만든다 — 발행회사명·상장일은 비어 보인다(§10 #1).
 * @param
 * @returns
 * @hidden N
*/
scwin.initNewForm = function () {
    dma_mst.setEmptyValue();
    dlt_isu.removeAll();
    dlt_rsn.removeAll();

    dma_mst.set("isurCd", scwin.isurCd);
    dma_mst.set("remk", scwin.DEFAULT_REMK);

    if (scwin.selTp === "1" && !$c.util.isEmpty(scwin.isuCd)) {
        dlt_isu.setJSON([{ isuCd : scwin.isuCd, isuNm : scwin.isurNm, isurCd : scwin.isurCd }]);
    }

    scwin.setFormState();
};

/**
 * @method
 * @name scwin.applyDetail
 * @author Inswave
 * @date 2026. 10. 30
 * @description 업무처리번호로 상세를 조회해 화면에 담고 버튼 상태를 맞춘다. (원본 fn_search + dts_* OnLoadCompleted — §5.1)
 * @param {String} bzProcsNo 업무처리번호
 * @returns
 * @hidden N
*/
scwin.applyDetail = async function (bzProcsNo) {
    if (!await scwin.selectOne(bzProcsNo)) return;

    scwin.bzProcsNo = dma_mst.get("bzProcsNo") || bzProcsNo;
    if ($c.util.isEmpty(dma_mst.get("isurCd"))) dma_mst.set("isurCd", scwin.isurCd);

    scwin.setFormState();
};

/**
 * @method
 * @name scwin.setFormState
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규·수정에 따라 종목선택·버튼 활성을 정한다. (원본 fn_SetIsuCdBtnShow·buttonSet.setInsertStatus·setButtonSetWithDate — §6.1)
 *  - 종목선택: 신규이고 종목 기준(selTp 1)이 아닐 때만
 *  - 신규: [저장]만(insert)
 *  - 수정: 예고일이 오늘 이전이면 조회 전용(error), 오늘 포함 이후면 [수정]·[삭제]·[안내문작성](update) — 원본 setButtonSetWithDate(예고일, true)
 * @param
 * @returns
 * @hidden N
*/
scwin.setFormState = function () {
    const isNew = $c.util.isEmpty(scwin.bzProcsNo);

    img_SetIsuCd.setDisabled(!isNew || scwin.selTp === "1");

    if (isNew) {
        $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
        return;
    }
    $c.stf.setButtonSetWithDate(edt_AdmIsuNotiDd, true, "grpBtnBox", scwin.BTN_MAP);
};

/**
 * @method
 * @name scwin.checkDd
 * @author Inswave
 * @date 2026. 10. 30
 * @description 날짜 칸 검사 — 8자리이고 기준 이후인지. pcc checkDdTm 은 Gauce .text 를 읽어 쓸 수 없어 같은 기준·문구로 화면에서 본다(05621·08033 선례).
 * @param {Object} comp 달력 컴포넌트
 * @param {String} msg 항목명 (예: 관리종목지정예고)
 * @param {Boolean} includeCurDate true 면 오늘 포함 이후, false 면 익일 이후
 * @returns {Promise<Boolean>} 통과 여부
 * @hidden N
*/
scwin.checkDd = async function (comp, msg, includeCurDate) {
    const val = comp.getValue() ?? "";

    if (val.length !== 8) {
        await $c.win.alert("[" + msg + "일]을 정확히 입력하세요.");
        comp.focus();
        return false;
    }
    if (includeCurDate ? (scwin.curDate > val) : (scwin.curDate >= val)) {
        await $c.win.alert("[" + msg + "일]을 " + (includeCurDate ? "현재일" : "익일") + " 이후로 입력하세요.");
        comp.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 10. 30
 * @description 저장·수정 전 입력값을 검증한다. (원본 fn_CheckForm — §6.2)
 *
 * 순서와 문구는 원본을 따른다: 종목 → 예고일(8자리·현재일 이후) → 예정일(입력했으면 8자리·익일 이후) → 예정일 또는 주석 →
 * 주석 400byte → 예정일이 예고일 이후 → 예고사유 → 기타 4000byte.
 * 원본은 예정일을 늘 필수로 검사해 「예정일 또는 주석」 분기가 동작하지 않았다 — 명세 규칙(둘 중 하나 필수)대로 예정일은 입력했을 때만 본다(§8 #1).
 * @returns {Promise<Boolean>} 검증 통과 여부
 * @hidden N
*/
scwin.validate = async function () {
    if (dlt_isu.getRowCount() === 0) {
        await $c.win.alert("[관리종목지정예고 종목]을 선택하세요.");
        img_SetIsuCd.focus();
        return false;
    }

    if (!await scwin.checkDd(edt_AdmIsuNotiDd, "관리종목지정예고", true)) return false;

    const schdlDd = dma_mst.get("admisuDesignSchdlDd") ?? "";
    if (!$c.util.isEmpty(schdlDd) && !await scwin.checkDd(edt_AdmIsuNotiEndDd, "관리종목지정예정", false)) return false;

    if ($c.util.isEmpty(schdlDd) && $c.util.isEmpty(dma_mst.get("admisuDesignSchdlContn"))) {
        await $c.win.alert("[관리종목지정예정] 또는 [주석]을 입력하세요.");
        txb_AdmIsuNotiEndContn.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_AdmIsuNotiEndContn, 400, "주석")) return false;

    if (!$c.util.isEmpty(schdlDd) && dma_mst.get("admisunotiDd") >= schdlDd) {
        await $c.win.alert("[관리종목지정예정일]은  [관리종목지정예고일]이후로 입력하세요.");
        edt_AdmIsuNotiEndDd.focus();
        return false;
    }

    if (dlt_rsn.getRowCount() === 0) {
        await $c.win.alert("[지정사유]를 선택하세요.");
        btn_rsn_add.focus();
        return false;
    }

    if (!$c.stf.checkMaxLength(txa_Remk, 4000, "기타")) return false;

    return true;
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 저장. 검증 → 사용자 확인 → 화면 채번(14자리 확인) → 등록. (원본 fn_save — §6.4)
 * @param
 * @returns
 * @hidden N
*/
scwin.save = async function () {
    scwin.trJob = "I";

    if (!await scwin.validate()) return;

    // "[저장] 처리를 하시겠습니까?" 확인 — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    const bzProcsNo = await scwin.getNewBzProcsNo();
    if (bzProcsNo.length !== 14) {
        // "MSG-0010": 업무처리번호 채번 실패 안내
        await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        return;
    }

    scwin.bzProcsNo = bzProcsNo;
    if (!await scwin.saveTrs(scwin.trJob)) scwin.bzProcsNo = "";    // 등록 실패면 신규 상태로 되돌린다
};

/**
 * @method
 * @name scwin.update
 * @author Inswave
 * @date 2026. 10. 30
 * @description 수정. 검증 → 사용자 확인 → 수정. (원본 fn_update — §6.4)
 * @param
 * @returns
 * @hidden N
*/
scwin.update = async function () {
    scwin.trJob = "U";

    if (!await scwin.validate()) return;

    // "[수정] 처리를 하시겠습니까?" 확인 — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.saveTrs(scwin.trJob);
};

/**
 * @method
 * @name scwin.remove
 * @author Inswave
 * @date 2026. 10. 30
 * @description 삭제. 사용자 확인 뒤 삭제한다. (원본 fn_delete — §6.4)
 * @param
 * @returns
 * @hidden N
*/
scwin.remove = async function () {
    scwin.trJob = "D";

    // "[삭제] 처리를 하시겠습니까?" 확인 — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.removeTrs();
};

/**
 * @method
 * @name scwin.openRsnPopup
 * @author Inswave
 * @date 2026. 10. 30
 * @description 사유찾기(관리종목지정사유) 팝업을 열고 고른 사유를 예고사유 그리드에 더한다. 이미 있는 사유면 안내하고 넣지 않는다. (원본 fn_PopFindClssLstRsnCd + fn_SetParRsnCd — §6.5)
 *
 * 원본 fn_GetParRsnCd 의 arr[0] "1"(시장)·arr[1] "07"(사유구분)·arr[5] "N"(기업인수목적회사)을 data 로 넘긴다(08032·08034 와 같음).
 * 중복 확인은 화면에서 0부터 센다 — pcc isNewValueForDataSet 은 1부터 세어 첫 행을 보지 못한다(§8 #3).
 * @param
 * @returns
 * @hidden N
*/
scwin.openRsnPopup = async function () {
    const res = await $c.lc.popFindClssLstRsnCd(scwin.RSNCD_ADM_DESIGN, { mkt : "1", rsn : "07", spac : "N" });
    if (res?.isCloseButtonClick === true || $c.util.isEmpty(res?.code)) return;    // 취소·닫기

    const rows = dlt_rsn.getAllJSON();
    if (rows.some(row => row.admisuDesignRsnCd === res.code)) {
        await $c.win.alert("이미 선택하신 사유가 있습니다.");
        return;
    }

    const row = dlt_rsn.insertRow();
    dlt_rsn.setCellData(row, "admisuDesignRsnCd", res.code);
    dlt_rsn.setCellData(row, "admisuDesignRsnNm", res.name ?? "");
};

/**
 * @method
 * @name scwin.getRsnNm
 * @author Inswave
 * @date 2026. 10. 30
 * @description 공시안내문 마스터의 지정사유 문장 — 「M월 D일 현재 {사유 및 사유} 사유로 인하여, 6월말|12월말」. (원본 fn_getRsnNm — §6.6)
 *
 * 예고일이 비면 「O월 O일」, 예고월이 7월 이후면 「12월말」. 같은 사유명은 한 번만 잇는다.
 * @returns {String} 지정사유 문장
 * @hidden N
*/
scwin.getRsnNm = function () {
    const notiDd = dma_mst.get("admisunotiDd") ?? "";
    const strDate = (notiDd.length === 8) ? notiDd.substring(4, 6) + "월 " + notiDd.substring(6, 8) + "일" : "O월 O일";
    const strHalfYear = (notiDd.substring(4, 6) > "06") ? "12월말" : "6월말";

    const names = [];
    dlt_rsn.getAllJSON().forEach(row => {
        const nm = row.admisuDesignRsnNm ?? "";
        if (names.join(" 및 ").indexOf(nm) < 0) names.push(nm);
    });

    return strDate + " 현재 " + names.join(" 및 ") + " 사유로 인하여, " + strHalfYear;
};

/**
 * @method
 * @name scwin.getDsclData
 * @author Inswave
 * @date 2026. 10. 30
 * @description 공시안내문작성(ULDSTF92024)에 넘길 값. 원본 fn_dscl 이 fn_GetPar 로 채우던 arr[0..5] 와 데이터셋 3개(종목·마스터·사유)다. (§6.6)
 *
 * 마스터에는 원본처럼 지정사유 문장(admisuRsnNm)과 고른 종목의 발행회사명(comNm)을 넣는다. 공시제목(arr[5])은 고른 종목의 종목명이다.
 * 원본은 arr[4] 를 비우고 arr[5] 를 넣어 길이 6 — 92024 는 본문을 생성하지 않는 서식으로 본다(원본 그대로).
 * @param
 * @returns {Object} 넘길 data
 * @hidden N
*/
scwin.getDsclData = function () {
    const focused = grd_isu.getFocusedRowIndex();
    const isu = dlt_isu.getRowJSON(focused < 0 ? 0 : focused) ?? {};

    return {
        formCd : scwin.DSCL_FORM_CD,                            // 원본 arr[0] "68347"
        bzProcsNo : scwin.bzProcsNo,                            // 원본 arr[1]
        isurCd : dma_mst.get("isurCd") || scwin.isurCd,         // 원본 arr[2]
        mktId : scwin.DSCL_MKT_ID,                              // 원본 arr[3] "1"
        msg : "",                                               // 원본 arr[4] 비움
        title : isu.isuNm ?? "",                                // 원본 arr[5] 종목명
        isu : dlt_isu.getAllJSON(),                             // 원본 CopyDataSet(dts_Isu)
        mst : [{ ...dma_mst.getJSON(), admisuRsnNm : scwin.getRsnNm(), comNm : isu.comNm ?? "" }],  // 원본 CopyDataSet(dts_Mst) + ADMISU_RSN_NM·COM_NM
        rsn : dlt_rsn.getAllJSON()                              // 원본 CopyDataSet(dts_Rsn)
    };
};

/**
 * @method
 * @name scwin.writeDscl
 * @author Inswave
 * @date 2026. 10. 30
 * @description 공시안내문작성. 공시안내문작성 팝업(ULDSTF92024)을 data 로 넘겨 열고 닫힐 때까지 기다린다. (원본 fn_dscl — §6.6)
 *
 * 원본은 닫힌 뒤 다시 조회하지 않는다.
 * @param
 * @returns
 * @hidden N
*/
scwin.writeDscl = async function () {
    const options = {
        id : "ULDSTF92024",
        popupName : "공시안내문작성",
        width : 745,
        height : 825,
        type : "pageFramePopup"
    };

    // TODO: 경로는 conversion-front 선례(/ui/listingcommon/), 92024 는 아직 getPar 계약이라 수신부 변경 필요 (§10 #5)
    await $c.win.openPopup("/ui/listingcommon/ULDSTF92024.xml", options, scwin.getDsclData());
};

/**
 * @method
 * @name scwin.getPar
 * @author Inswave
 * @date 2026. 10. 30
 * @description [호환용 · 임시] 공시안내문작성(ULDSTF92024) 전환본은 아직 부모의 scwin.getPar 를 이름으로 불러 값을 받는다.
 * 92024 가 $c.data.getParameter() 수신으로 바뀌면 이 함수를 지운다. (§6.6, §10 #5, 가이드 §6.5 예외)
 * @param {Array} arr 92024 가 넘기는 빈 배열 — [0] 서식코드 [1] 업무처리번호 [2] 발행기관코드 [3] 시장구분 [4] 비움 [5] 공시제목
 * @param {Object} dltIsu 92024 의 종목 dataList
 * @param {Object} dltMst 92024 의 마스터 dataList
 * @param {Object} dlt2 92024 의 원천 자료 2 (예고사유)
 * @returns {Number} arr 길이
 * @hidden N
*/
scwin.getPar = function (arr, dltIsu, dltMst, dlt2) {
    const data = scwin.getDsclData();

    arr[0] = data.formCd;
    arr[1] = data.bzProcsNo;
    arr[2] = data.isurCd;
    arr[3] = data.mktId;
    arr[4] = data.msg;
    arr[5] = data.title;

    scwin.fillDataList(dltIsu, data.isu);
    scwin.fillDataList(dltMst, data.mst);
    scwin.fillDataList(dlt2, data.rsn);

    return arr.length;
};

/**
 * @method
 * @name scwin.fillDataList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 컬럼 정의가 비어 있는 92024 의 원천 dataList 에 행 키를 컬럼으로 더하고 행을 채운다. (원본 CopyDataSet 의 헤더 복사 — §6.6)
 * @param {Object} dataList 채울 dataList
 * @param {Array} rows 행 배열
 * @returns
 * @hidden N
*/
scwin.fillDataList = function (dataList, rows) {
    if (!dataList) return;

    Object.keys(rows[0] ?? {}).forEach(key => {
        if (dataList.getColumnIndex(key) < 0) dataList.insertColumn(key);
    });
    dataList.setJSON(rows);
};
